python3 -c 'from bs4 import BeautifulSoup; import os,sys
for name in (\"regular\",\"distance\",\"glance\",\"prospectus\"):
 print(\"---\",name,\"---\")
 s=BeautifulSoup(open(os.environ[\"site_tmp\"]+\"/\"+name+\".html\",encoding=\"utf-8\"),\"html.parser\")
