   cells=[x.get_text(\" \",strip=True) for x in tr.select(\"th,td\")]
   if cells: print(\" | \".join(cells))
  for a in t.select(\"a[href]\"): print(\"LINK\",a.get_text(\" \",strip=True),\"|\",a.get(\"href\"))
 print()'"

